import React, { useState } from 'react';
import './BuggyCalculator.css';

/**
 * 🐛 DEBUGGING CHALLENGE COMPONENT 🐛
 * 
 * This calculator has several intentional bugs that require debugging skills:
 * - Console logging to trace issues
 * - Using browser inspector to examine state
 * - Understanding data types and event handling
 * 
 * Instructions for students:
 * 1. Try using the calculator - notice what doesn't work
 * 2. Open Developer Tools (F12 or right-click → Inspect)
 * 3. Check the Console tab for any errors
 * 4. Add console.log statements to understand the flow
 * 5. Use the React Developer Tools to inspect component state
 */

function BuggyCalculator() {
  const [display, setDisplay] = useState('0');
  const [previousValue, setPreviousValue] = useState(null);
  const [operation, setOperation] = useState(null);
  const [waitingForOperand, setWaitingForOperand] = useState(false);

  // 🐛 BUG #1: This function has a logical error
  const inputNumber = (num) => {
    console.log('Input number called with:', num); // This console.log is helpful!

    if (waitingForOperand) {
      setDisplay(num);
      setWaitingForOperand(false);
    } else {
      // BUG: What happens when display is '0'? 
      setDisplay(display === '0' ? num : display + num);
    }
  };

  // 🐛 BUG #2: Missing console logs make this hard to debug
  const inputOperation = (nextOperation) => {
    const inputValue = parseFloat(display);

    if (previousValue === null) {
      setPreviousValue(inputValue);
    } else if (operation) {
      const currentValue = previousValue || 0;
      const newValue = calculate(currentValue, inputValue, operation);

      // BUG: What's the value here? Add console.log to find out!
      setDisplay(String(newValue));
      setPreviousValue(newValue);
    }

    setWaitingForOperand(true);
    setOperation(nextOperation);
  };

  // 🐛 BUG #3: This calculate function has multiple issues
  const calculate = (firstValue, secondValue, operation) => {
    // Students need to add console.logs here to see what's happening

    switch (operation) {
      case '+':
        return firstValue + secondValue;
      case '-':
        return firstValue - secondValue;
      case '*':
        return firstValue * secondValue;
      case '/':
        // BUG: What about division by zero?
        return firstValue / secondValue;
      case '=':
        return secondValue;
      default:
        return secondValue;
    }
  };

  // 🐛 BUG #4: This function has a data type issue
  const inputDot = () => {
    console.log('Dot clicked, current display:', display, 'type:', typeof display);

    if (waitingForOperand) {
      setDisplay('0.');
      setWaitingForOperand(false);
    } else if (display.indexOf('.') === -1) {
      // BUG: What if display is a number instead of string?
      setDisplay(display + '.');
    }
  };

  // 🐛 BUG #5: Clear function doesn't reset everything
  const clear = () => {
    console.log('Clear called');
    setDisplay('0');
    // BUG: Are we clearing everything we should?
  };

  // 🐛 BUG #6: This has an event handling issue
  const performCalculation = () => {
    const inputValue = parseFloat(display);

    if (previousValue !== null && operation) {
      const newValue = calculate(previousValue, inputValue, operation);
      setDisplay(String(newValue));
      setPreviousValue(null);
      setOperation(null);
      setWaitingForOperand(true);
    }
  };

  return (
    <div className="buggy-calculator">
      <h2>🐛 Debugging Challenge: Broken Calculator</h2>
      <div className="calculator-instructions">
        <p><strong>Mission:</strong> This calculator has bugs! Use your debugging skills:</p>
        <ol>
          <li>Open Developer Tools (F12)</li>
          <li>Try the calculator and notice what breaks</li>
          <li>Add console.log statements to trace the issues</li>
          <li>Use the inspector to examine component state</li>
        </ol>
      </div>

      <div className="calculator">
        <div className="display">{display}</div>

        <div className="buttons">
          <button onClick={clear} className="clear">C</button>
          <button onClick={() => inputOperation('/')} className="operator">÷</button>
          <button onClick={() => inputOperation('*')} className="operator">×</button>
          <button onClick={() => inputOperation('-')} className="operator">-</button>

          <button onClick={() => inputNumber('7')}>7</button>
          <button onClick={() => inputNumber('8')}>8</button>
          <button onClick={() => inputNumber('9')}>9</button>
          <button onClick={() => inputOperation('+')} className="operator">+</button>

          <button onClick={() => inputNumber('4')}>4</button>
          <button onClick={() => inputNumber('5')}>5</button>
          <button onClick={() => inputNumber('6')}>6</button>
          <button onClick={performCalculation} className="equals" rowSpan="2">=</button>

          <button onClick={() => inputNumber('1')}>1</button>
          <button onClick={() => inputNumber('2')}>2</button>
          <button onClick={() => inputNumber('3')}>3</button>

          <button onClick={() => inputNumber('0')} className="zero">0</button>
          <button onClick={inputDot}>.</button>
        </div>
      </div>

      <div className="debug-info">
        <h3>🔍 Debug Information</h3>
        <p><strong>Current State:</strong></p>
        <ul>
          <li>Display: {display} (type: {typeof display})</li>
          <li>Previous Value: {previousValue}</li>
          <li>Operation: {operation}</li>
          <li>Waiting for Operand: {waitingForOperand ? 'Yes' : 'No'}</li>
        </ul>
      </div>
    </div>
  );
}

export default BuggyCalculator;
